def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    mod = 1_000_000_007
    size = len(alphabet)
    char_index = {ch: i for i, ch in enumerate(alphabet)}

    children = [[-1] * size]
    terminal = [False]

    for word in banned:
        state = 0
        for ch in word:
            i = char_index[ch]
            if children[state][i] == -1:
                children[state][i] = len(children)
                children.append([-1] * size)
                terminal.append(False)
            state = children[state][i]
        terminal[state] = True

    failure = [0] * len(children)
    queue = deque()

    for i in range(size):
        child = children[0][i]
        if child == -1:
            children[0][i] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]
        for i in range(size):
            child = children[state][i]
            if child == -1:
                children[state][i] = children[failure[state]][i]
            else:
                failure[child] = children[failure[state]][i]
                queue.append(child)

    safe_states = [state for state in range(len(children)) if not terminal[state]]
    index = {state: i for i, state in enumerate(safe_states)}
    count = len(safe_states)

    matrix = [[0] * count for _ in range(count)]
    for state in safe_states:
        row = matrix[index[state]]
        for target in children[state]:
            if not terminal[target]:
                row[index[target]] += 1

    vector = [0] * count
    vector[index[0]] = 1

    while n:
        if n & 1:
            result = [0] * count
            for i, value in enumerate(vector):
                if value:
                    for j, weight in enumerate(matrix[i]):
                        result[j] += value * weight
            vector = [value % mod for value in result]

        n >>= 1
        if n:
            squared = [[0] * count for _ in range(count)]
            for i in range(count):
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, weight in enumerate(matrix[k]):
                            squared[i][j] += value * weight
                squared[i] = [value % mod for value in squared[i]]
            matrix = squared

    return sum(vector) % mod
